<h1 tabindex="-1">{{ position.instrument.symbol }}</h1>
<nav class="position-switcher" aria-label="選擇部位"><a v-for="p in siblings" :key="p.id" :href="positionUrl(p.id)" :aria-current="p.id===position.id?'page':undefined" @click.prevent="openPosition(p.id)">{{ p.instrument.exchange||'交易所未填' }} · {{ product(p.instrument.product) }} · {{ direction(p.instrument.direction) }} · 部位 {{ label(p) }}</a></nav>
<section id="holding-summary"><h2>持倉摘要</h2><p class="local-state">{{ position.snapshot?.captured_date|| (position.origin==='ledger'?'依已記錄成交計算':'日期未確認') }} <span v-if="position.snapshot">· 目前採用的畫面</span><span v-if="position.visibility==='not_current'"> · 不再列入目前持倉</span></p>
