<details><summary>部位操作</summary><button :disabled="busy" @click="setVisibility">{{ position.visibility==='current'?'不再列為目前持倉':'列入目前持倉' }}</button><p>這只改變清單狀態，沒有記錄賣出或已實現收益。</p><label v-if="position.snapshot_ids.length>1">摘要採用畫面<select :value="position.selected_snapshot_id" @change="selectSnapshot($event.target.value)"><option v-for="s in state.snapshots.filter(s=>position.snapshot_ids.includes(s.id))" :key="s.id" :value="s.id">{{ s.captured_date||'日期未確認' }} · {{ s.sources[0]?.name }} · {{ s.id.slice(-12) }}</option></select></label></details>
</section>
<nav class="detail-anchors" aria-label="同頁閱讀"><a href="#holding-summary">摘要</a><a href="#decision-timeline">時間線</a><a href="#event-reading-title">理由與回顧</a></nav>
<div class="decision-columns"><section id="decision-timeline"><div class="page-heading"><h2>買賣與決策時間線</h2><button @click="openShort('decision')">記錄決定</button></div><label>事件種類<select v-model="eventKind"><option value="all">全部</option><option value="execution">成交與證據</option><option value="decision">決定</option><option value="review">回顧</option></select></label><label class="check-label"><input type="checkbox" v-model="showWithdrawn"/>顯示已撤回紀錄</label><p v-if="!events.length">這個部位尚無符合的事件。</p>
<ol class="decision-timeline"><li v-for="(event,i) in events" :key="event.id"><h3 class="timeline-date" v-if="i===0||events[i-1].date!==event.date">{{ event.date||'日期未確認' }}<small v-if="event.date&&events.some(v=>v.id!==event.id&&v.date===event.date)">當日順序未確認</small></h3><button :aria-pressed="event.id===selectedEvent?.id" @click="selectEvent(event.id)"><strong>{{ event.title }}</strong><span>{{ event.payload?.reason?.slice(0,90)|| (event.kind==='snapshot'?'尚未記錄理由':outcomes[event.payload?.outcome]||'') }}</span><small v-if="event.status==='withdrawn'">已撤回</small></button><DecisionEvent v-if="event.id===selectedEvent?.id" class="mobile-event" :event="event" :reviews="eventReviews(event)" @edit="openShort" @toggle="toggleEntry"/></li></ol></section>
<div class="desktop-event"><button v-if="selectedEvent" @click="readDetails">讀取這筆詳情</button><DecisionEvent v-if="selectedEvent" :event="selectedEvent" :reviews="eventReviews(selectedEvent)" @edit="openShort" @toggle="toggleEntry"/></div></div>
</template><div v-else class="empty-state"><h1 tabindex="-1">找不到這筆紀錄</h1><p>它可能已撤回或連結不完整。</p><a :href="listUrl" @click.prevent="backToList">返回持倉清單</a></div>
</template>
<template v-else-if="mode==='review'">
<div class="page-heading"><h1 tabindex="-1">決策回顧</h1><button class="primary" @click="openAdd">新增紀錄</button></div>
<div class="holding-filters"><label>搜尋理由或標的<input v-model="reviewSearch"/></label><label>回顧狀態<select v-model="reviewFilter"><option value="all">全部</option><option value="pending">待回顧／待觀察</option><option value="supported">支持原判斷</option><option value="weakened">削弱原判斷</option><option value="mixed">結果混合</option></select></label><label>事件起日<input type="date" v-model="reviewStart"/></label><label>事件迄日<input type="date" v-model="reviewEnd"/></label></div>
<p v-if="!reviewRows.length">尚未記錄決策理由，或沒有符合篩選的決定。從持倉詳頁補記後，即可回顧。</p><ul class="review-list"><li v-for="row in reviewRows" :key="row.event.id"><a :href="positionUrl(row.position.id,row.event.id)" @click.prevent="openPosition(row.position.id,row.event.id)"><strong>{{ row.position.instrument.symbol }} · {{ row.event.date||'事件日期未確認' }}</strong><p>{{ row.event.payload.reason.slice(0,180) }}</p><span>{{ outcomes[row.latest?.payload?.outcome||row.latest?.outcome||'pending'] }}</span></a></li></ul>
<details><summary>已記錄完整成交的回顧統計</summary><ReviewInsights :state="state" :reports="reports" @navigate="(id,record)=>$emit('navigate',id,record)"/></details>
</template>
<template v-else>
