<div class="holding-filters"><label>搜尋標的或交易所<input v-model="filters.q" placeholder="搜尋標的或交易所"/></label><label>商品<select v-model="filters.product"><option value="">全部商品</option><option v-for="(label,key) in products" :key="key" :value="key">{{ label }}</option></select></label><label class="desktop-filter">交易所<select v-model="filters.exchange"><option value="">全部交易所</option><option value="unknown">交易所未填</option><option v-for="exchange in exchanges" :key="exchange">{{ exchange }}</option></select></label><label class="desktop-filter">狀態<select v-model="filters.visibility"><option value="current">目前持倉</option><option value="not_current">不再列入持倉</option><option value="all">所有紀錄</option></select></label><label class="desktop-filter">排序<select v-model="filters.sort"><option value="symbol">標的</option><option value="recent">最近記錄</option></select></label><div class="mobile-filter-toggle"><button :aria-expanded="moreFilters" @click="moreFilters=!moreFilters">篩選 {{ filterCount }}</button></div></div>
<details class="holding-advanced" :open="moreFilters" @toggle="moreFilters=$event.target.open"><summary>更多篩選<span v-if="filterCount"> · {{ filterCount }}</span></summary><div class="holding-filters"><label class="mobile-filter">交易所<select v-model="filters.exchange"><option value="">全部交易所</option><option value="unknown">交易所未填</option><option v-for="exchange in exchanges" :key="exchange">{{ exchange }}</option></select></label><label class="mobile-filter">狀態<select v-model="filters.visibility"><option value="current">目前持倉</option><option value="not_current">不再列入持倉</option><option value="all">所有紀錄</option></select></label><label class="mobile-filter">排序<select v-model="filters.sort"><option value="symbol">標的</option><option value="recent">最近記錄</option></select></label><label>方向<select v-model="filters.direction"><option value="">全部方向</option><option value="long">做多</option><option value="short">做空</option><option value="unknown">未提供</option></select></label><label class="check-label"><input type="checkbox" v-model="filters.gaps"/>只看資料待補</label><button @click="resetFilters">重設篩選</button></div></details>
<p v-if="!filtered.length" class="empty-state">{{ positions.length?'沒有符合的紀錄。重設篩選，或選「所有紀錄」查看證據。':'持倉目前空白。按新增紀錄整理第一張持倉畫面。' }} <button v-if="positions.length" @click="resetFilters">重設篩選</button></p>
<table v-else class="holdings-table"><caption class="sr-only">持倉與紀錄清單，各部位獨立呈現</caption><thead><tr><th scope="col" :aria-sort="filters.sort==='symbol'?'ascending':'none'">標的與部位</th><th scope="col">商品與交易所</th><th scope="col">畫面數值／成交股數</th><th scope="col">日期與理由</th><th scope="col">讀取</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id" :id="rowId(p.id)"><th scope="row"><a :href="positionUrl(p.id)" @click.prevent="openPosition(p.id)">{{ p.instrument.symbol }}</a><span>部位 {{ label(p) }}{{ p.origin==='ledger'?' · 成交帳本':'' }}</span></th><td>{{ p.instrument.exchange||'交易所未填' }} · {{ product(p.instrument.product) }} · {{ direction(p.instrument.direction) }}<span v-if="p.snapshot?.fields.leverage">{{ p.snapshot.fields.leverage.value }}×</span></td><td class="holding-amount"><span>{{ p.snapshot?amountLabel(p.snapshot):p.origin==='ledger'?'已記錄成交股數':'尚無持倉畫面' }}</span><strong>{{ p.snapshot?amount(p.snapshot):p.calculation?.quantity??'未提供' }}</strong></td><td><span>{{ p.snapshot?.captured_date||(p.origin==='ledger'?'依成交日期':'日期未確認') }}</span><span>{{ reasonState(p) }}</span></td><td><a :aria-label="'查看 '+p.instrument.symbol+' 部位 '+label(p)" :href="positionUrl(p.id)" @click.prevent="openPosition(p.id)">查看部位</a></td></tr></tbody></table>
</template>
<dialog ref="editor" class="decision-editor" @cancel.prevent="closeShort"><form v-if="shortForm" @submit.prevent="saveShort"><div class="page-heading"><h2>{{ shortForm.type==='exchange'?'編輯部位資料':shortForm.type==='review'?'後續回顧':shortForm.type==='record'?'修改成交理由':shortForm.type==='reason'?'事後補記理由':'記錄決定' }}</h2><button type="button" @click="closeShort">關閉</button></div><p v-if="shortStale" class="canonical-alert">其他分頁已更新資料。草稿保留，請載入最新後重新核對。</p><div v-if="error" tabindex="-1" role="alert" ref="dialogError"><p>{{ error }}</p><a href="#short-main" @click.prevent="focusShort">返回欄位修正</a><button type="button" @click="reloadShort">載入最新後重新核對</button></div>
<template v-if="shortForm.type==='exchange'"><label>交易所<input id="short-main" v-model="shortForm.exchange" maxlength="100"/></label><p>保留未知日期與數值；交易所更正來源標示為使用者確認。</p></template>
<template v-else-if="shortForm.type==='review'"><label>回顧日期<input type="date" v-model="shortForm.date" required/></label><label>這如何影響原判斷<select v-model="shortForm.outcome"><option v-for="(label,key) in outcomes" :key="key" :value="key">{{ label }}</option></select></label><label>後來看到了什麼／學到什麼<textarea id="short-main" v-model="shortForm.lesson" rows="5" maxlength="5000"/></label><label>下一步<textarea v-model="shortForm.next_action" rows="3" maxlength="5000"/></label></template>
<template v-else><p v-if="shortForm.type==='reason'" class="local-state">事後補記 · 保存時間由系統記錄</p><label v-if="shortForm.type!=='record'">動作<select v-model="shortForm.action"><option v-for="(label,key) in actions" :key="key" :value="key">{{ label }}</option></select></label><label>事件日期（未知可留空）<input type="date" v-model="shortForm.date" :disabled="shortForm.type==='record'"/></label><label>理由（必填）<textarea id="short-main" v-model="shortForm.reason" required maxlength="5000" rows="5" aria-describedby="reason-help"/></label><p id="reason-help" class="muted">保存你自己的文字；新決定不代表已完成買賣。</p><label>預期<textarea v-model="shortForm.expectation" maxlength="5000" rows="3"/></label><label>改變看法的條件<textarea v-model="shortForm.invalidation" maxlength="5000" rows="3"/></label><details><summary>更多決策依據</summary><label>主要風險<textarea v-model="shortForm.risk" maxlength="5000" rows="3"/></label><label>觀察期間<input v-model="shortForm.horizon" maxlength="200"/></label><label>引用報告版本<select v-model="shortForm.report_id"><option value="">不引用報告</option><option v-for="r in reports" :key="r.bundle_id" :value="r.bundle_id">{{ r.security.ticker }} · {{ r.revision_id }}</option></select></label></details></template>
<div class="editor-savebar"><span>{{ busy?'保存中':saveStatus==='conflict'?'版本衝突':'未保存' }}</span><button class="primary" :disabled="busy||shortStale">{{ shortForm.type==='review'?'保存回顧':shortForm.type==='exchange'?'保存部位資料':'保存理由' }}</button><button type="button" @click="closeShort">取消</button></div></form></dialog>
</template>
</section>
</template>
<script setup>
import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue';import {usePrivateState} from './private-state.js';import {projectPositions,timeline,copy,ensurePosition,editJournalEntry,reviewsForEvent} from './decision-workspace.mjs';import {snapshotFields} from './snapshot-core.mjs';import CaptureComposer from './CaptureComposer.vue';import DecisionEvent from './DecisionEvent.vue';import ReviewInsights from './ReviewInsights.vue';import {siteIndex} from './api.js';
const props=defineProps({mode:String,active:Boolean});defineEmits(['navigate']);
const {state,loaded,loading,busy,error,message,storage,authRequired,scope,revision,load,save,context,saveStatus}=usePrivateState();
const route=ref({}),filters=ref({q:'',product:'',exchange:'',visibility:'current',sort:'symbol',direction:'',gaps:false}),eventKind=ref('all'),showWithdrawn=ref(false),selectedId=ref(''),reports=ref([]),shortForm=ref(null),editor=ref(null),dialogError=ref(null),saveError=ref(null),composer=ref(null),reviewSearch=ref(''),reviewFilter=ref('all'),reviewStart=ref(''),reviewEnd=ref(''),moreFilters=ref(false),shortBase=ref(null);let listUrl='?workspace=ledger',listY=0,lastPosition='',returnUrl='?workspace=ledger',originalShort='',trigger=null,popLock=false,lastRouteUrl=location.pathname+location.search;
const products={perpetual:'永續',spot:'現貨',stock_token:'股票代幣',bot:'機器人',unknown:'未提供'},outcomes={pending:'待觀察',supported:'支持原判斷',weakened:'削弱原判斷',mixed:'結果混合'},actions={observe:'觀察',hold:'繼續持有',increase:'考慮增加',reduce:'考慮減少',exit:'考慮退出',unspecified:'尚未分類'};
const product=v=>products[v]||v,direction=v=>({long:'做多',short:'做空',unknown:'方向未提供'}[v]),value=f=>f?new Intl.NumberFormat('zh-TW',{maximumFractionDigits:12}).format(f.value)+' '+f.unit:'未提供',amountLabel=s=>s.fields.total_profit?'畫面總利潤':'畫面未實現盈虧',amount=s=>value(s.fields.total_profit||s.fields.unrealized_pnl),rowId=id=>'holding-'+encodeURIComponent(id);
const fieldGroups=[{name:'價格與風險',keys:['leverage','extra_margin','latest_price','liquidation_price','take_profit','stop_loss']},{name:'資金費',keys:['funding_rate','funding_amount']},{name:'畫面統計',keys:['quantity','investment','display_value','total_profit_percent','unrealized_percent','realized_pnl','realized_percent','cumulative_pnl','cumulative_percent']}];
const positions=computed(()=>projectPositions(state.value)),currentSnapshots=computed(()=>positions.value.filter(p=>p.origin==='snapshot'&&p.visibility==='current')),snapshotSymbols=computed(()=>new Set(currentSnapshots.value.map(p=>p.instrument.symbol)).size),ledgerPositions=computed(()=>positions.value.filter(p=>p.origin==='ledger'&&p.visibility==='current')),exchanges=computed(()=>[...new Set(positions.value.map(p=>p.instrument.exchange).filter(Boolean))].sort());
const position=computed(()=>positions.value.find(p=>p.id===route.value.position)|| (route.value.record?positions.value.find(p=>p.origin==='ledger'&&state.value.records.some(r=>r.id===route.value.record&&p.id===`ledger:${r.ticker}:${r.currency}`)):null)),siblings=computed(()=>positions.value.filter(p=>p.instrument.symbol===position.value?.instrument.symbol));
const intakeContext=computed(()=>({...(position.value?.instrument||{symbol:route.value.ticker||'',product:'unknown',direction:'unknown',exchange:null}),position_id:position.value?.id||null,report_id:route.value.report||'',report_label:reports.value.find(r=>r.bundle_id===route.value.report)?.revision_id||''}));
const label=p=>String.fromCharCode(65+positions.value.filter(v=>v.instrument.symbol===p.instrument.symbol).findIndex(v=>v.id===p.id));
const allEvents=computed(()=>position.value?timeline(state.value,position.value):[]),events=computed(()=>allEvents.value.filter(e=>(showWithdrawn.value||e.status!=='withdrawn')&&(eventKind.value==='all'||eventKind.value==='execution'&&['record','execution_evidence'].includes(e.kind)||eventKind.value==='review'&&['review','legacy_review'].includes(e.kind)||e.kind===eventKind.value))),selectedEvent=computed(()=>events.value.find(e=>e.id===selectedId.value)||events.value.find(e=>e.kind==='decision')||events.value.find(e=>e.kind==='record')||events.value.find(e=>e.id===position.value?.selected_snapshot_id)||events.value[0]);
const filterCount=computed(()=>[filters.value.exchange,filters.value.direction,filters.value.visibility!=='current',filters.value.gaps].filter(Boolean).length);
const shortStale=computed(()=>shortForm.value&&shortBase.value&&(shortBase.value.expectedScope!==scope.value||shortBase.value.expectedRevision!==revision.value));
function eventReviews(e){return reviewsForEvent(state.value,e);}
function reasonState(p){if(p.origin==='ledger')return '已保存成交理由';return state.value.journal?.entries.some(e=>e.position_id===p.id&&e.kind==='decision'&&e.status==='active')?'已記錄理由':'尚未記錄理由';}
const filtered=computed(()=>{const f=filters.value,q=f.q.trim().toLowerCase();let ps=positions.value.filter(p=>(f.visibility==='all'||p.visibility===f.visibility)&&(!q||(p.instrument.symbol+' '+(p.instrument.exchange||'交易所未填')).toLowerCase().includes(q))&&(!f.product||p.instrument.product===f.product)&&(!f.exchange||(f.exchange==='unknown'?!p.instrument.exchange:p.instrument.exchange===f.exchange))&&(!f.direction||p.instrument.direction===f.direction)&&(!f.gaps||!p.snapshot?.captured_date||!p.instrument.exchange));if(f.sort==='recent')ps=ps.sort((a,b)=>(b.updated_at||'').localeCompare(a.updated_at||'')||a.id.localeCompare(b.id));return ps;});
const reviewRows=computed(()=>positions.value.flatMap(p=>timeline(state.value,p).filter(e=>['decision','record'].includes(e.kind)&&e.status==='active').map(event=>({position:p,event,latest:eventReviews(event).at(-1)}))).filter(r=>(r.position.instrument.symbol+' '+r.event.payload.reason).toLowerCase().includes(reviewSearch.value.toLowerCase())&&(reviewFilter.value==='all'||(r.latest?.payload?.outcome||r.latest?.outcome||'pending')===reviewFilter.value)&&(!reviewStart.value||r.event.date>=reviewStart.value)&&(!reviewEnd.value||r.event.date&&r.event.date<=reviewEnd.value)));
function readRoute(){const p=new URLSearchParams(location.search);if(route.value.view==='add'&&p.get('view')!=='add'&&composer.value?.dirty&&!confirm('離開會放棄這個分頁尚未保存的草稿。是否離開？')){history.pushState(history.state,'',lastRouteUrl);return;}lastRouteUrl=location.pathname+location.search;route.value={view:p.get('view'),position:p.get('position'),record:p.get('record'),method:p.get('method'),ticker:p.get('ticker'),report:p.get('report')};selectedId.value=p.get('event')||p.get('record')||'';if(!route.value.position&&!route.value.record&&route.value.view!=='add'){filters.value={q:p.get('holdingQ')||p.get('ticker')||'',product:p.get('product')||'',exchange:p.get('exchange')||'',visibility:p.get('visibility')||'current',sort:p.get('sort')||'symbol',direction:p.get('direction')||'',gaps:p.get('gaps')==='1'};listUrl=location.pathname+location.search;}}
function setUrl(url){history.pushState(history.state,'',url);window.dispatchEvent(new PopStateEvent('popstate'));nextTick(()=>document.querySelector('.decision-workspace h1')?.focus());}
function positionUrl(id,event){const p=new URLSearchParams({workspace:'ledger',position:id});if(event)p.set('event',event);return '?'+p;}
function openPosition(id,event){if(!route.value.position&&!route.value.record){listUrl=location.pathname+location.search;listY=window.scrollY;}lastPosition=id;setUrl(positionUrl(id,event));window.scrollTo({top:0,behavior:'instant'});}
function backToList(){message.value='';setUrl(listUrl);nextTick(()=>{window.scrollTo({top:listY,behavior:'instant'});document.getElementById(rowId(lastPosition))?.querySelector('a')?.focus({preventScroll:true});});}
function openAdd(){returnUrl=location.pathname+location.search;const p=new URLSearchParams({workspace:'ledger',view:'add'});if(position.value)p.set('position',position.value.id);if(route.value.ticker)p.set('ticker',route.value.ticker);if(route.value.report)p.set('report',route.value.report);setUrl('?'+p);}
function returnFromAdd(){setUrl(returnUrl);}
function resetFilters(){filters.value={q:'',product:'',exchange:'',visibility:'current',sort:'symbol',direction:'',gaps:false};}
watch(filters,()=>{if(route.value.position||route.value.view==='add'||route.value.record)return;const f=filters.value,p=new URLSearchParams({workspace:props.mode==='review'?'review':'ledger'});for(const [k,v] of Object.entries(f))if(v&&!(k==='visibility'&&v==='current')&&!(k==='sort'&&v==='symbol'))p.set(k==='q'?'holdingQ':k,k==='gaps'?'1':v);history.replaceState(history.state,'','?'+p);listUrl=location.pathname+location.search;},{deep:true});
function selectEvent(id){selectedId.value=id;const p=new URLSearchParams(location.search);p.set('event',id);history.replaceState(history.state,'','?'+p);}
function readDetails(){document.querySelector('.desktop-event #event-reading-title')?.focus();}
async function openShort(type,event=selectedEvent.value){trigger=document.activeElement;shortBase.value=context();error.value='';const now=new Date().toISOString(),existing=event?.kind==='decision'||event?.kind==='review'||event?.kind==='legacy_review'?event:null;
 if(type==='exchange')shortForm.value={type,id:position.value.snapshot.id,exchange:position.value.instrument.exchange||''};
 else if(type==='review'){const editing=['review','legacy_review'].includes(event?.kind),payload=editing?(event.payload||event):{};shortForm.value={type,id:editing?event.id:crypto.randomUUID(),legacy:event?.kind==='record'||event?.kind==='legacy_review',record_id:event?.record_id||event?.id,review_of:editing?payload.review_of:event?.id,date:editing?(event.event_date||event.date):now.slice(0,10),outcome:payload.outcome||'pending',lesson:payload.lesson||'',next_action:payload.next_action||''};}
 else shortForm.value={type,id:existing?.id|| (type==='record'?event.id:crypto.randomUUID()),date:existing?.event_date|| (type==='record'?event.date:''),action:'unspecified',reason:'',expectation:'',risk:'',invalidation:'',horizon:'',report_id:'',...(existing?.payload|| (type==='record'?event.payload:{})),authorship:existing?.payload.authorship||(type==='reason'?'retrospective':'new_decision'),snapshot_id:event?.kind==='snapshot'?event.id:null};
 originalShort=JSON.stringify(shortForm.value);await nextTick();editor.value.showModal();}
function closeShort(){if(busy.value)return;if(shortForm.value&&JSON.stringify(shortForm.value)!==originalShort&&!confirm('放棄尚未保存的修改？'))return;editor.value?.close();shortForm.value=null;nextTick(()=>trigger?.focus());}
function focusShort(){document.getElementById('short-main')?.focus();}
async function reloadShort(){await load();if(shortForm.value&&loaded.value){shortBase.value=context();error.value='';message.value='已載入最新資料。請比較原欄位與草稿，再明確保存。';}}
async function reloadForDraft(){await load();}
async function saveShort(){const f=shortForm.value,now=new Date().toISOString();if(!f||shortStale.value)return;let candidate=copy(state.value);
 if(f.type==='exchange')candidate.snapshots=candidate.snapshots.map(s=>s.id===f.id?{...s,exchange:f.exchange.trim()||null,exchange_source:{kind:'user_confirmed',confirmed_at:now,note:'使用者在部位資料核對交易所。'}}:s);
 else if(f.type==='record')candidate.records=candidate.records.map(r=>r.id===f.id?{...r,...Object.fromEntries(['reason','expectation','risk','invalidation','horizon','report_id'].map(k=>[k,f[k]])),revision:r.revision+1,updated_at:now}:r);
 else if(f.type==='review'&&f.legacy){const review={id:f.id,record_id:f.record_id,date:f.date,outcome:f.outcome,lesson:f.lesson,next_action:f.next_action};candidate.reviews=[...candidate.reviews.filter(r=>r.id!==f.id),review];}
 else{const kind=f.type==='review'?'review':'decision',payload=kind==='review'?{review_of:f.review_of,outcome:f.outcome,lesson:f.lesson,next_action:f.next_action}:Object.fromEntries(['action','reason','expectation','risk','invalidation','horizon','authorship','report_id'].map(k=>[k,f[k]]));candidate=editJournalEntry(candidate,position.value.id,payload,{kind,id:f.id,event_date:f.date||null,now});if(f.snapshot_id)candidate.journal.entries.find(e=>e.id===f.id).source_refs=[{snapshot_id:f.snapshot_id,source_ordinal:0}];}
 if(await save(candidate,f.type==='review'?'回顧已保存。':'紀錄已保存。',shortBase.value)){editor.value.close();shortForm.value=null;selectedId.value=f.id;nextTick(()=>trigger?.focus());}else{await nextTick();dialogError.value?.focus();}}
async function toggleEntry(event){const next=copy(state.value),now=new Date().toISOString(),field=event.kind==='record'?'records':'journal';const array=field==='records'?next.records:next.journal?.entries,e=array?.find(v=>v.id===event.id);if(!e)return;e.status=e.status==='active'?'withdrawn':'active';e.revision++;e.updated_at=now;await save(next,'紀錄狀態已保存。',context());}
async function setVisibility(){if(position.value.origin==='ledger'){error.value='成交帳本的持倉由已記錄股數決定，請核對實際成交。';return;}const next=copy(state.value);ensurePosition(next,position.value.id);const p=next.journal.positions.find(p=>p.id===position.value.id);if(p.selected_snapshot_id===null&&p.visibility!=='current'){error.value='沒有持倉畫面的證據不能列入目前持倉。';return;}p.visibility=p.visibility==='current'?'not_current':'current';p.revision++;p.updated_at=new Date().toISOString();await save(next,'持倉清單狀態已保存。',context());}
async function selectSnapshot(id){const next=copy(state.value);ensurePosition(next,position.value.id);const p=next.journal.positions.find(p=>p.id===position.value.id);p.selected_snapshot_id=id;p.revision++;p.updated_at=new Date().toISOString();await save(next,'摘要採用畫面已保存。',context());}
async function saveIntake(preview,base,done){if(preview.already_applied){message.value=preview.receipt.status==='withdrawn'?'這個批次已撤回，請到資料管理明確復原。':'這個批次已保存，沒有重複新增。';const id=preview.receipt.candidate_receipts.find(r=>r.position_id)?.position_id;done(true);if(id)openPosition(id);else returnFromAdd();return;}const ok=await save(preview.state,'已保存 '+preview.counts.new+' 個部位與 '+preview.counts.evidence+' 筆成交證據。',base);done(ok);if(!ok){await nextTick();saveError.value?.focus();}if(ok){const p=preview.receipt.candidate_receipts.find(r=>r.position_id)?.position_id;if(p)openPosition(p);else returnFromAdd();}}
function leave(e){if(composer.value?.dirty&&!confirm('離開會放棄這個分頁尚未保存的草稿。是否離開？'))e.preventDefault();if(shortForm.value)e.preventDefault();}
function beforeUnload(e){if(composer.value?.dirty||shortForm.value&&JSON.stringify(shortForm.value)!==originalShort){e.preventDefault();e.returnValue='';}}
watch(scope,(v,p)=>{if(p&&v!==p){editor.value?.close();shortForm.value=null;selectedId.value='';}});
watch(()=>props.active,v=>{if(v)load();});
readRoute();onMounted(()=>{window.addEventListener('popstate',readRoute);window.addEventListener('workspace-leave',leave);window.addEventListener('beforeunload',beforeUnload);siteIndex().then(v=>reports.value=v.catalog.bundles).catch(()=>{});});onUnmounted(()=>{window.removeEventListener('popstate',readRoute);window.removeEventListener('workspace-leave',leave);window.removeEventListener('beforeunload',beforeUnload);});
</script>
